<script setup>
import { ref,reactive,computed,onMounted,watch } from 'vue';import { useRoute,useRouter } from 'vue-router';import { Check,ArrowLeft,ArrowRight,ShieldCheck,Clock,Plus,Minus,BedDouble } from 'lucide-vue-next';import { api,session } from '../lib/api';import { currency,today,nextDate,dateText } from '../lib/format';import { notify } from '../lib/ui';import StatePanel from '../components/StatePanel.vue';
const route=useRoute(),router=useRouter();const step=ref(1),rooms=ref([]),selected=ref([]),loading=ref(false),busy=ref(false),error=ref(''),profile=ref(null),accepted=ref(false);
const form=reactive({check_in:route.query.check_in||today(),check_out:route.query.check_out||nextDate(today()),adults:Number(route.query.adults)||2,children:Number(route.query.children)||0,special_request:''});
const nights=computed(()=>Math.max(0,Math.round((Date.parse(form.check_out)-Date.parse(form.check_in))/86400000)));const total=computed(()=>selected.value.reduce((sum,r)=>sum+Number(r.price_per_night)*nights.value,0));
async function search(){error.value='';loading.value=true;selected.value=[];try{if(form.check_out<=form.check_in)throw Error('วันเช็กเอาต์ต้องหลังวันเข้าพัก');rooms.value=(await api('/rooms/availability?'+new URLSearchParams({check_in:form.check_in,check_out:form.check_out,adults:form.adults,children:form.children,limit:100}))).data;if(route.query.room_id){const r=rooms.value.find(r=>String(r.room_id)===String(route.query.room_id));if(r)toggle(r);}}catch(e){error.value=e.message;}finally{loading.value=false;}}
function toggle(room){const i=selected.value.findIndex(r=>r.room_id===room.room_id);if(i>=0)selected.value.splice(i,1);else if(selected.value.length<20)selected.value.push({...room,adult_count:form.adults,child_count:form.children});}
function next(){error.value='';if(!selected.value.length){error.value='กรุณาเลือกห้องพักอย่างน้อยหนึ่งห้อง';return;}if(step.value===2&&!profile.value){error.value='ไม่พบข้อมูลลูกค้า กรุณาตรวจข้อมูลส่วนตัว';return;}step.value++;window.scrollTo({top:0,behavior:'smooth'});}
async function confirm(){busy.value=true;error.value='';try{if(!accepted.value)throw Error('กรุณายืนยันรายละเอียดการจอง');const {data}=await api('/bookings',{method:'POST',body:{check_in_date:form.check_in,check_out_date:form.check_out,rooms:selected.value.map(r=>({room_id:r.room_id,adult_count:r.adult_count,child_count:r.child_count})),special_request:form.special_request}});notify('สร้างการจองสำเร็จ');router.replace({path:'/bookings/'+data.booking_id,query:{created:'1'}});}catch(e){error.value=e.message;if(e.code==='ROOM_ALREADY_BOOKED')step.value=1;}finally{busy.value=false;}}
watch(()=>[form.check_in,form.check_out,form.adults,form.children],()=>{selected.value=[];rooms.value=[];});
onMounted(async()=>{await search();try{profile.value=(await api('/me/profile')).data;}catch(e){error.value=e.message;}});
</script>
<template><div class="container section compact"><p class="eyebrow">YOUR STAY, YOUR WAY</p><h1>จองห้องพัก</h1><div class="steps"><div v-for="(title,i) in ['เลือกห้อง','ผู้เข้าพัก','ตรวจรายละเอียด','ยืนยันการจอง']" :key="title" :class="{current:step===i+1,done:step>i+1}"><span><Check v-if="step>i+1" :size="16"/><template v-else>{{ i+1 }}</template></span>{{ title }}</div></div><div v-if="error" class="alert danger" role="alert">{{ error }}</div><div class="booking-layout"><section class="panel"><template v-if="step===1"><h2>เลือกห้องสำหรับการเข้าพัก</h2><form class="form-grid search-inline" @submit.prevent="search"><label>วันเข้าพัก<input type="date" v-model="form.check_in" :min="today()" required/></label><label>วันเช็กเอาต์<input type="date" v-model="form.check_out" :min="nextDate(form.check_in)" required/></label><label>ผู้ใหญ่ต่อห้อง<input type="number" v-model.number="form.adults" min="1" max="100" required/></label><label>เด็กต่อห้อง<input type="number" v-model.number="form.children" min="0" max="100" required/></label><button class="btn outline span-2" :disabled="loading">ค้นหาห้องว่างใหม่</button></form><StatePanel :loading="loading" :empty="!loading&&!rooms.length&&!error"/><div v-for="room in rooms" :key="room.room_id" class="select-room" :class="{selected:selected.some(r=>r.room_id===room.room_id)}"><div class="room-mini-icon"><BedDouble/></div><div><h3>{{ room.type_name }} <small>ห้อง {{ room.room_number }}</small></h3><p class="muted">{{ room.adult_capacity }} ผู้ใหญ่ · {{ room.child_capacity }} เด็ก · {{ room.bed_type }}</p><strong>{{ currency(room.price_per_night) }} <small>/ คืน</small></strong></div><button class="btn" :class="selected.some(r=>r.room_id===room.room_id)?'primary':'outline'" @click="toggle(room)">{{ selected.some(r=>r.room_id===room.room_id)?'เลือกแล้ว':'เลือกห้อง' }}</button></div><button class="btn primary full" :disabled="!selected.length||loading" @click="next">ข้อมูลผู้เข้าพัก <ArrowRight :size="18"/></button></template><template v-if="step===2"><h2>ข้อมูลผู้เข้าพัก</h2><p class="muted">การจองนี้ผูกกับบัญชี {{ session.user?.username }}</p><div v-if="profile" class="profile-summary"><strong>{{ profile.first_name }} {{ profile.last_name }}</strong><span>{{ profile.phone }}</span><span>{{ session.user?.email }}</span><RouterLink to="/profile" class="text-link">แก้ไขข้อมูลส่วนตัว</RouterLink></div><div v-for="room in selected" :key="room.room_id" class="guest-allocation"><h3>{{ room.type_name }} · ห้อง {{ room.room_number }}</h3><div class="form-grid"><label>ผู้ใหญ่<input type="number" v-model.number="room.adult_count" min="1" :max="room.adult_capacity" required/></label><label>เด็ก<input type="number" v-model.number="room.child_count" min="0" :max="room.child_capacity" required/></label></div></div><label>คำขอเพิ่มเติม <small>(ไม่บังคับ)</small><textarea v-model="form.special_request" maxlength="5000" rows="3" placeholder="ระบุคำขอเพิ่มเติมสำหรับโรงแรม"></textarea></label><div class="button-row"><button class="btn outline" @click="step--"><ArrowLeft :size="16"/> ย้อนกลับ</button><button class="btn primary" @click="next" :disabled="selected.some(r=>!Number.isInteger(r.adult_count)||r.adult_count<1||r.adult_count>r.adult_capacity||!Number.isInteger(r.child_count)||r.child_count<0||r.child_count>r.child_capacity)">ตรวจรายละเอียด <ArrowRight :size="16"/></button></div></template><template v-if="step===3"><h2>ตรวจสอบรายละเอียด</h2><div class="summary-dates"><div><small>วันเข้าพัก</small><strong>{{ dateText(form.check_in) }}</strong></div><ArrowRight :size="20"/><div><small>วันเช็กเอาต์</small><strong>{{ dateText(form.check_out) }}</strong></div></div><div v-for="room in selected" :key="room.room_id" class="summary-line"><div><strong>{{ room.type_name }} · {{ room.room_number }}</strong><small>{{ room.adult_count }} ผู้ใหญ่ · {{ room.child_count }} เด็ก · {{ nights }} คืน</small></div><strong>{{ currency(Number(room.price_per_night)*nights) }}</strong></div><p v-if="form.special_request" class="muted">คำขอ: {{ form.special_request }}</p><div class="alert info"><Clock :size="18"/><span>การจองจะถือห้อง 30 นาที โปรดส่งหลักฐานและติดต่อโรงแรมเพื่อตรวจสอบภายในเวลาที่กำหนด</span></div><div class="button-row"><button class="btn outline" @click="step--">ย้อนกลับ</button><button class="btn primary" @click="next">ไปยืนยันการจอง <ArrowRight :size="16"/></button></div></template><template v-if="step===4"><div class="confirmation-icon"><ShieldCheck :size="40"/></div><h2>พร้อมสำหรับการพักผ่อนแล้วไหม?</h2><p class="muted">ยืนยันเพื่อสร้างเลขการจอง จากนั้นส่งหลักฐานการชำระเงินและเอกสารยืนยันตัวตน</p><div class="alert info">ก่อนเข้าพักต้องชำระค่าห้องครบและมีเอกสารที่โรงแรมอนุมัติ</div><label class="checkbox"><input type="checkbox" v-model="accepted"/>ฉันตรวจสอบวันที่ ห้องพัก และจำนวนผู้เข้าพักแล้ว</label><div class="button-row"><button class="btn outline" @click="step--" :disabled="busy">ย้อนกลับ</button><button class="btn primary" @click="confirm" :disabled="busy||!accepted">{{ busy?'กำลังสร้างการจอง…':'ยืนยันการจอง' }}</button></div></template></section><aside class="panel booking-summary"><p class="eyebrow">YOUR RESERVATION</p><h3>สรุปการเข้าพัก</h3><div class="summary-line"><span>วันที่</span><strong>{{ dateText(form.check_in) }}</strong></div><div class="summary-line"><span>ระยะเวลา</span><strong>{{ nights }} คืน</strong></div><div class="summary-line"><span>ห้องที่เลือก</span><strong>{{ selected.length }} ห้อง</strong></div><div class="summary-line" v-for="room in selected" :key="room.room_id"><span>{{ room.type_name }}</span><strong>{{ currency(Number(room.price_per_night)*nights) }}</strong></div><div class="summary-total"><span>ยอดค่าห้องรวม</span><strong>{{ currency(total) }}</strong></div><small>ค่าใช้จ่ายเพิ่มเติมระหว่างเข้าพักจะคิดแยก<br/>ราคาสุดท้ายตรวจสอบจากระบบเมื่อยืนยัน</small><div class="secure-note"><ShieldCheck :size="17"/>จองผ่านบัญชีของคุณ</div></aside></div></div></template>
